using System;using System.Collections.Generic;using System.Linq;using UnityEngine;using UnityEditor;
public static class SkillDataInstall {
 static string Folder(TrainingCommand c){switch(c){case TrainingCommand.Light:return "5LP";case TrainingCommand.Medium:return "5MP";case TrainingCommand.Heavy:return "5HP";case TrainingCommand.Slash:return "5LK";case TrainingCommand.HeavySlash:return "5MK";case TrainingCommand.StrongKick:return "5HK";case TrainingCommand.CrouchWeakKick:return "2LK";case TrainingCommand.CrouchMediumKick:return "2MK";case TrainingCommand.CrouchStrongKick:return "2HK";case TrainingCommand.CrouchWeakPunch:return "2LP";case TrainingCommand.CrouchMediumPunch:return "2MP";case TrainingCommand.CrouchStrongPunch:return "2HP";case TrainingCommand.AirStrongPunch:return "jHP";case TrainingCommand.AirStrongKick:return "jHK";case TrainingCommand.AirDownStrongKick:return "j2HK";default:return "Compatibility/"+c;}}
 public static void Run(){var source=AssetDatabase.LoadAssetAtPath<TrainingMoveSet>("Assets/Shioka/調整Data/Fighter/Awari/Skill/Moves.asset");if(source.catalog.Length>0)throw new Exception("Already adopted; refuse overwrite");var entries=new List<(string,TrainingMove)>();for(int i=0;i<source.moves.Length;i++)entries.Add(("move:"+i,source.moves[i]));foreach(string name in new[]{"sweep","special","special2","forwardSpecial1","airStrongKickMove","airDownStrongKickMove","airStrongPunchMove","airSpecial2Move"}){var move=(TrainingMove)typeof(TrainingMoveSet).GetProperty(name).GetValue(source);if(move!=null)entries.Add((name,move));}var refs=new List<TrainingMoveReference>();foreach(var item in entries){string root="Assets/Shioka/調整Data/Fighter/Awari/Skill/"+Folder(item.Item2.command);Ensure(root);string path=AssetDatabase.GenerateUniqueAssetPath(root+"/Data.asset");var data=ScriptableObject.CreateInstance<TrainingMoveData>();data.data=JsonUtility.FromJson<TrainingMove>(JsonUtility.ToJson(item.Item2));if(JsonUtility.ToJson(data.data)!=JsonUtility.ToJson(item.Item2))throw new Exception("Serialization changed values");AssetDatabase.CreateAsset(data,path);refs.Add(new TrainingMoveReference{role=item.Item1,asset=data});}source.catalog=refs.ToArray();source.ClearAdoptedLegacy();EditorUtility.SetDirty(source);AssetDatabase.SaveAssetIfDirty(source);Debug.Log("SKILL_DATA "+refs.Count+" definitions copied exactly; catalog contains references only");}
 static void Ensure(string path){if(AssetDatabase.IsValidFolder(path))return;int i=path.LastIndexOf('/');Ensure(path.Substring(0,i));AssetDatabase.CreateFolder(path.Substring(0,i),path.Substring(i+1));}
}
